/* ---------- photo storage (browser only, memory fallback) ---------- */

var mem = {};
var PK = "aethelra-photo:";
function getPhoto(k) {
  try {
    var v = localStorage.getItem(PK + k);
    if (v) return v;
  } catch (e) {}
  return mem[k] || PHOTOS[k] || null;
}
function setPhoto(k, url) {
  if (!url) {
    delete mem[k];
    try {
      localStorage.removeItem(PK + k);
    } catch (e) {}
    return true;
  }
  try {
    localStorage.setItem(PK + k, url);
    delete mem[k];
    return true;
  } catch (e) {
    mem[k] = url;
    return false;
  }
}
function getFav(id) {
  try {
    return localStorage.getItem("aethelra-fav:" + id) === "1";
  } catch (e) {
    return !!mem["fav:" + id];
  }
}
function setFav(id, on) {
  try {
    on
      ? localStorage.setItem("aethelra-fav:" + id, "1")
      : localStorage.removeItem("aethelra-fav:" + id);
  } catch (e) {
    mem["fav:" + id] = on;
  }
}

function esc(s) {
  return String(s).replace(/[&<>"]/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
  });
}
